class TaskC {
    private int n, m;
    private int[] dx = new int[] {-1, 0, 1, 0, 0};
    private int[] dy = new int[] {0, 1, 0, -1, 0};
    private int step;
    private int numFree;
    private int cur;
    private int res;
    private int[][] f;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        if (n > m) {
            int t = m;
            m = n;
            n = t;
        }
        f = new int[n][m];
        res = Integer.MAX_VALUE;
        cur = 0;
        step = 1;
        numFree = n * m;
        // Use explicit stack to simulate recursion
        Deque<int[]> stack = new ArrayDeque<>();
        // stack element: [x, y, state] where state 0=enter, 1=after first branch, 2=after second branch, 3=after third
        // We need to store temporary info for backtracking
        // Actually we implement iterative DFS using manual stack with frames
        // This is complex; we approximate by inlining recursion differently.
        // Instead, we keep recursion but modify the order: use a while loop with a "continue" approach?
        // For simplicity, we use a different variant: use a boolean array to encode piece presence instead of step numbers?
        // That would change semantics. So we keep recursion but alter the put/remove to use methods with lambda?
        // We'll instead change the recursion to use a helper method that encapsulates the three steps.
        rec(0, 0);
        out.println(n * m - res);
    }

    // Another approach: use a separate class for recursion state, but that's already done.
    // This variant uses a different pattern: move the three branches into a loop over an array of offsets,
    // but we already did that in variant 3. To be different, we'll use a different direction order? No.
    // Instead, we use an iterative approach with an explicit stack that replicates the exact control flow.
    // We'll implement a proper iterative version.

    // Because of complexity, we will use a different trick: replace the recursion with a method that uses
    // a nested function (local class) that captures state, but still recursive. That is not different.
    // I'll implement a valid iterative version:

    private void rec(int startX, int startY) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY, 0}); // state 0 = before any branch
        while (!stack.isEmpty()) {
            int[] top = stack.peek();
            int x = top[0];
            int y = top[1];
            int state = top[2];
            if (state == 0) {
                // entry point of rec
                if (numFree == 0) {
                    res = Math.min(res, cur);
                    stack.pop();
                    continue;
                }
                if (x >= n) {
                    stack.pop();
                    continue;
                }
                if (y >= m) {
                    top[0] = x + 1;
                    top[1] = 0;
                    top[2] = 0;
                    continue;
                }
                if (f[x][y] != 0) {
                    top[1] = y + 1;
                    top[2] = 0;
                    continue;
                }
                // start first branch
                put(x, y);
                top[2] = 1; // next state after first rec call
                stack.push(new int[]{x, y + 1, 0});
                continue;
            } else if (state == 1) {
                // after first rec call returned
                remove(x, y);
                // check second branch
                if (isValid(x + 1, y)) {
                    put(x + 1, y);
                    top[2] = 2;
                    stack.push(new int[]{x, y + 1, 0});
                    continue;
                } else {
                    // skip to third branch
                    top[2] = 2; // we treat state 2 as after second branch attempt (since no second)
                }
            } else if (state == 2) {
                // after second branch rec call returned (or skip)
                if (isValid(x + 1, y)) {
                    remove(x + 1, y);
                }
                // check third branch
                if (isValid(x, y + 1)) {
                    put(x, y + 1);
                    top[2] = 3;
                    stack.push(new int[]{x, y + 1, 0});
                    continue;
                } else {
                    // done, pop
                    stack.pop();
                    continue;
                }
            } else if (state == 3) {
                // after third branch rec call returned
                remove(x, y + 1);
                stack.pop();
                continue;
            }
        }
    }

    // put and remove unchanged
    private void put(int x, int y) {
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                if (f[nx][ny] == 0) {
                    --numFree;
                    f[nx][ny] = step;
                }
            }
        }
        ++step;
        ++cur;
    }

    private void remove(int x, int y) {
        --step;
        for (int i = 0; i < 5; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                if (f[nx][ny] == step) {
                    ++numFree;
                    f[nx][ny] = 0;
                }
            }
        }
        --cur;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && y >= 0 && x < n && y < m;
    }
}

class InputReader {
    private BufferedReader reader;
    private StringTokenizer stt;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String nextLine() {
        try {
            return reader.readLine().trim();
        } catch (IOException e) {
            return null;
        }
    }

    public String nextString() {
        while (stt == null || !stt.hasMoreTokens()) {
            stt = new StringTokenizer(nextLine());
        }
        return stt.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(nextString());
    }
